settings.custom_css:
/* Vertically center heading text with the checkbox icon */
selector .elementor-icon-list-items > li.elementor-icon-list-item {
  align-items: center;
  padding-top: 0 !important;
  padding-bottom: 0 !important;
}
/* Clear separation BEFORE each feature group (heading preceded by a bullet) */
selector .elementor-icon-list-items > li:not(.elementor-icon-list-item) + li.elementor-icon-list-item {
  margin-top: 12px !important;
}
/* Tight, consistent gap between a heading and its first bullet */
selector .elementor-icon-list-items > li.elementor-icon-list-item + li {
  margin-top: 6px !important;
}
/* Consistent gap between bullet lines */
selector .elementor-icon-list-items > li:not(.elementor-icon-list-item) + li:not(.elementor-icon-list-item) {
  margin-top: 6px !important;
}
/* A little breathing room between the title and the list */
selector { margin-top: 16px; }

